#include "cost_quote_report.hpp"
#include "artifact_io.hpp"
#include <sstream>

namespace trading {
void CostQuoteReport::write(const std::filesystem::path &directory, const nlohmann::json &summary) const {
    std::filesystem::create_directories(directory);
    std::ostringstream page;
    page
        << R"html(<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Historical quote window coverage</title><style>body{font:16px/1.5 system-ui;background:#f2f5f8;color:#17354b;margin:0}main{max-width:1150px;margin:28px auto;padding:0 20px}section{background:white;border:1px solid #d5e0e7;border-radius:8px;padding:20px;margin:18px 0}select{font:inherit;padding:8px}svg{width:100%;background:#f5f8fa}table{width:100%;border-collapse:collapse}th,td{text-align:right;padding:7px;border-bottom:1px solid #dce5ec}th:first-child,td:first-child{text-align:left}pre{white-space:pre-wrap;overflow-wrap:anywhere;font-size:13px}.scroll{overflow:auto}</style><main><h1>Historical quote window coverage</h1><p id="origin"></p><p>Fixed old SIP windows use the first common operational date per year. Eligibility is evaluated on the latest record after complete pagination. Missing, invalid, ambiguous or capped windows remain unestimated.</p><p>Quoted half-spread is a sampled crossing-cost reference. It is not a realized fill, complete strategy cost or observed network latency. It is not added to an all-in cost assumption.</p><section><label>Instrument <select id="symbol"></select></label> <label>Year <select id="year"></select></label><p id="coverage"></p><p><span style="color:#177da3">Blue: one-minute delay</span>; <span style="color:#b45c26">orange: two-minute delay</span>. Smaller orange marks preserve coincident blue observations.</p><svg id="chart" viewBox="0 0 1000 300" role="img" aria-label="Sampled half-spread by decision offset"></svg></section><section><h2>Selected windows</h2><div class="scroll"><table><thead><tr><th>Reference UTC</th><th>Decision / delay, min</th><th>Status</th><th>Pages / records</th><th>Half-spread, bp</th><th>Bid / ask shares</th><th>Age, ms</th></tr></thead><tbody id="rows"></tbody></table></div></section><section><h2>Acquisition and scope</h2><pre id="scope"></pre><p><a href="summary.json">Complete manifest</a></p></section><script>const data=)html"
        << summary.dump() << R"html(;
const symbol=document.getElementById('symbol'),year=document.getElementById('year');
for(const s of data.plan.symbols){const o=document.createElement('option');o.value=s;o.textContent=s;symbol.append(o)}
for(const s of [...new Set(data.plan.sample_dates.map(d=>d.slice(0,4)))]){const o=document.createElement('option');o.value=s;o.textContent=s;year.append(o)}
document.getElementById('origin').textContent=data.evidence_origin==='synthetic'?'Constructed diagnostic: no historical quotes or strategy outcomes were loaded.':'Historical SIP sample: observed quotes, with hypothetical execution interpretation.';
function draw(){const rows=data.windows.filter(r=>r.symbol===symbol.value&&r.date.startsWith(year.value)),eligible=rows.filter(r=>r.status==='eligible');document.getElementById('coverage').textContent=eligible.length+' / '+rows.length+' eligible windows; unestimated '+(rows.length-eligible.length);
const max=Math.max(1,...eligible.map(r=>r.measurement.half_spread_bps));let chart=`<text x="10" y="22">${max.toFixed(3)} bp</text><text x="10" y="270">0</text><text x="400" y="295">Decision offset from session open, minutes</text>`;
for(const r of eligible){const x=80+(r.decision_minute-30)/355*850,y=255-r.measurement.half_spread_bps/max*220;chart+=`<circle cx="${x}" cy="${y}" r="${r.delay_minutes===1?6:3}" fill="${r.delay_minutes===1?'#177da3':'#b45c26'}"><title>${r.end}: ${r.measurement.half_spread_bps.toFixed(6)} bp; delay ${r.delay_minutes} min</title></circle>`}chart+='<text x="80" y="277">30</text><text x="915" y="277">385</text>';document.getElementById('chart').innerHTML=chart;
document.getElementById('rows').innerHTML=rows.map(r=>{const m=r.measurement;return `<tr><td>${r.end}</td><td>${r.decision_minute} / ${r.delay_minutes}</td><td>${r.status}</td><td>${r.pages.length} / ${r.records}</td><td>${r.status==='eligible'?m.half_spread_bps.toFixed(6):'NA'}</td><td>${m?m.bid_shares+' / '+m.ask_shares:'NA'}</td><td>${m?(m.age_nanoseconds/1e6).toFixed(6):'NA'}</td></tr>`}).join('');}
symbol.addEventListener('change',draw);year.addEventListener('change',draw);symbol.value=data.plan.symbols[0];year.value=data.plan.sample_dates[0].slice(0,4);draw();document.getElementById('scope').textContent=JSON.stringify({status:data.status,counts:data.status_counts,retained_attempts:data.retained_http_attempts,new_requests:data.network_requests_this_invocation,policy:data.policy_sha256,source:data.source_sha256,historical_strategy_scored:data.historical_strategy_scored,reserved_strategy_inputs_opened:data.reserved_strategy_inputs_opened},null,2);</script></main></html>)html";
    write_new_text_file(directory / "report.html", page.str());
    write_new_text_file(directory / "summary.json", summary.dump(2) + '\n');
}
} // namespace trading
